svgPath:
function svgPath(className, pathData, attributes = {}) {
  const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
  path.classList.add(...className.split(" "));
  path.setAttribute("d", pathData);
  for (const [attribute, value] of Object.entries(attributes)) path.setAttribute(attribute, value);
  return path;
}

drawWhatsAppTabbedPanelFrame:
function drawWhatsAppTabbedPanelFrame() {
  const rail = $("#whatsapp-stage-tabs");
  const frame = $("#whatsapp-tabbed-panel-frame");
  const shell = $("#whatsapp-view .whatsapp-workspace-shell");
  const workspace = $("#whatsapp-workspace");
  if (!rail || !frame || !shell || !workspace) return;
  const shellRect = shell.getBoundingClientRect();
  const workspaceRect = workspace.getBoundingClientRect();
  const panelWidth = Math.round(shellRect.width);
  const panelHeight = Math.round(shellRect.height);
  const panelTop = Math.round(workspaceRect.top - shellRect.top);
  const activeButton = rail.querySelector(".whatsapp-process-tab.is-active");
  if (!activeButton || !panelWidth || !panelHeight) return;
  const stageButtons = [...rail.querySelectorAll(".whatsapp-process-tab")];
  const panelCorner = 11;
  const tabGeometry = (button) => {
    const rect = button.getBoundingClientRect();
    const tabLeft = Math.round(rect.left - shellRect.left);
    const tabRight = tabLeft + Math.round(rect.width);
    const tabLeftRoot = Math.max(0, tabLeft - 3);
    const tabRightRoot = Math.min(panelWidth, tabRight + 3);
    const outlineBody = `L ${tabLeft + 1} 10 C ${tabLeft + 2} 5 ${tabLeft + 6} 1 ${tabLeft + 13} 1 H ${tabRight - 11} C ${tabRight - 5} 1 ${tabRight - 2} 5 ${tabRight - 1} 10 L ${tabRightRoot} ${panelTop}`;
    const outlinePath = `M ${tabLeftRoot} ${panelTop} ${outlineBody}`;
    return {
      tabLeft,
      tabRight,
      tabLeftRoot,
      tabRightRoot,
      outlineBody,
      outlinePath,
      fillPath: `${outlinePath} H ${tabLeftRoot} Z`,
      activeFillPath: `${outlinePath} V ${panelTop + 2} H ${tabLeftRoot} V ${panelTop} Z`,
    };
  };
  const activeGeometry = tabGeometry(activeButton);
  const panelSurface = `M ${panelCorner} ${panelTop} H ${panelWidth - panelCorner} Q ${panelWidth} ${panelTop} ${panelWidth} ${panelTop + panelCorner} V ${panelHeight - panelCorner} Q ${panelWidth} ${panelHeight} ${panelWidth - panelCorner} ${panelHeight} H ${panelCorner} Q 0 ${panelHeight} 0 ${panelHeight - panelCorner} V ${panelTop + panelCorner} Q 0 ${panelTop} ${panelCorner} ${panelTop} Z`;
  const panelOutline = `M ${panelWidth} ${panelTop + panelCorner} V ${panelHeight - panelCorner} Q ${panelWidth} ${panelHeight} ${panelWidth - panelCorner} ${panelHeight} H ${panelCorner} Q 0 ${panelHeight} 0 ${panelHeight - panelCorner} V ${panelTop + panelCorner}`;
  const activeContour = `M 0 ${panelTop + panelCorner} Q 0 ${panelTop} ${panelCorner} ${panelTop} H ${activeGeometry.tabLeftRoot} M ${activeGeometry.tabRightRoot} ${panelTop} H ${panelWidth - panelCorner} Q ${panelWidth} ${panelTop} ${panelWidth} ${panelTop + panelCorner}`;
  frame.setAttribute("viewBox", `0 0 ${panelWidth} ${panelHeight}`);
  frame.setAttribute("preserveAspectRatio", "none");
  const definitions = svgElement("defs");
  const inactiveGradient = svgElement("pattern", {
    id: "whatsapp-tab-inactive-gradient",
    x: "0",
    y: "0",
    width: "1",
    height: String(panelTop),
    patternUnits: "userSpaceOnUse",
  });
  const inactiveTopColor = [22, 26, 23];
  const inactiveBottomColor = [17, 23, 19];
  for (let row = 0; row < panelTop; row += 1) {
    const progress = row / Math.max(1, panelTop - 1);
    const color = inactiveTopColor.map((channel, index) =>
      Math.round(channel + (inactiveBottomColor[index] - channel) * progress));
    inactiveGradient.append(svgElement("rect", {
      x: "0",
      y: String(row),
      width: "1",
      height: "1",
      fill: `rgb(${color.join(" ")})`,
    }));
  }
  const activeContourGradient = svgElement("linearGradient", {
    id: "whatsapp-active-contour-stroke",
    x1: "0",
    y1: String(panelTop),
    x2: String(panelWidth),
    y2: String(panelTop),
    gradientUnits: "userSpaceOnUse",
  });
  const contourOffset = (value) => `${(Math.max(0, Math.min(panelWidth, value)) / panelWidth * 100).toFixed(3)}%`;
  const contourStops = [
    [0, "#324137", ".62"],
    [activeGeometry.tabLeftRoot - 520, "#405b30", ".68"],
    [activeGeometry.tabLeftRoot - 180, "#769c32", ".84"],
    [activeGeometry.tabLeftRoot, "#c3ed3d", "1"],
    [activeGeometry.tabRightRoot, "#c3ed3d", "1"],
    [activeGeometry.tabRightRoot + 180, "#769c32", ".84"],
    [activeGeometry.tabRightRoot + 520, "#405b30", ".68"],
    [panelWidth, "#324137", ".62"],
  ];
  for (const [position, color, opacity] of contourStops) {
    activeContourGradient.append(svgElement("stop", {
      offset: contourOffset(position),
      "stop-color": color,
      "stop-opacity": opacity,
    }));
  }
  const panelStrokeGradient = svgElement("linearGradient", {
    id: "whatsapp-panel-outline-stroke",
    x1: "0",
    y1: String(panelTop),
    x2: String(panelWidth),
    y2: String(panelTop),
    gradientUnits: "userSpaceOnUse",
  });
  for (const [offset, color] of [["0%", "#566b34"], ["22%", "#536633"], ["55%", "#40522f"], ["82%", "#324137"], ["100%", "#324137"]]) {
    panelStrokeGradient.append(svgElement("stop", { offset, "stop-color": color }));
  }
  const outerHalo = svgElement("filter", {
    id: "whatsapp-tab-active-halo-outer",
    x: "-30%",
    y: "-80%",
    width: "160%",
    height: "260%",
    "color-interpolation-filters": "sRGB",
  });
  outerHalo.append(svgElement("feGaussianBlur", { stdDeviation: "2.3" }));
  const nearHalo = svgElement("filter", {
    id: "whatsapp-tab-active-halo-near",
    x: "-20%",
    y: "-50%",
    width: "140%",
    height: "200%",
    "color-interpolation-filters": "sRGB",
  });
  nearHalo.append(svgElement("feGaussianBlur", { stdDeviation: ".95" }));
  const exteriorHaloMask = svgElement("mask", {
    id: "whatsapp-active-exterior-mask",
    x: "-12",
    y: "-12",
    width: String(panelWidth + 24),
    height: String(panelHeight + 24),
    maskUnits: "userSpaceOnUse",
    maskContentUnits: "userSpaceOnUse",
  });
  exteriorHaloMask.append(
    svgElement("rect", { x: "-12", y: "-12", width: String(panelWidth + 24), height: String(panelHeight + 24), fill: "white" }),
    svgElement("path", { d: panelSurface, fill: "black" }),
    svgElement("path", { d: activeGeometry.activeFillPath, fill: "black" }),
  );
  definitions.append(inactiveGradient, activeContourGradient, panelStrokeGradient, outerHalo, nearHalo, exteriorHaloMask);
  frame.replaceChildren(definitions);

  frame.append(svgPath("whatsapp-tabbed-panel-frame__surface", panelSurface));
  for (const button of stageButtons) {
    if (button.classList.contains("is-active")) continue;
    const geometry = tabGeometry(button);
    frame.append(
      svgPath("whatsapp-tabbed-panel-frame__inactive", geometry.fillPath),
      svgPath("whatsapp-tabbed-panel-frame__inactive-outline", geometry.outlinePath),
    );
  }
  frame.append(
    svgPath("whatsapp-tabbed-panel-frame__outline", panelOutline),
    svgPath("whatsapp-tabbed-panel-frame__active-surface", activeGeometry.activeFillPath),
    svgPath("whatsapp-tabbed-panel-frame__active-contour whatsapp-tabbed-panel-frame__active-contour--outer", activeContour, { mask: "url(#whatsapp-active-exterior-mask)" }),
    svgPath("whatsapp-tabbed-panel-frame__active-contour whatsapp-tabbed-panel-frame__active-contour--near", activeContour, { mask: "url(#whatsapp-active-exterior-mask)" }),
    svgPath("whatsapp-tabbed-panel-frame__active-contour-outline", activeContour),
    svgPath("whatsapp-tabbed-panel-frame__active-halo whatsapp-tabbed-panel-frame__active-halo--outer", activeGeometry.outlinePath, { mask: "url(#whatsapp-active-exterior-mask)" }),
    svgPath("whatsapp-tabbed-panel-frame__active-halo whatsapp-tabbed-panel-frame__active-halo--near", activeGeometry.outlinePath, { mask: "url(#whatsapp-active-exterior-mask)" }),
    svgPath("whatsapp-tabbed-panel-frame__active-outline", activeGeometry.outlinePath),
  );
}

css:
:root {
  color-scheme: dark;
  --ink: #111311;
  --ink-soft: #2a2e2b;
  --paper: #f7f7f3;
  --canvas: #e9eae5;
  --line: #c9ccc5;
  --line-dark: #555b56;
  --blue: #2767ff;
  --signal: #dcff52;
  --danger: #ba2c2c;
  --muted: #6f756f;
  --shadow: 0 24px 70px rgb(17 19 17 / 18%);
  font-family: "Segoe UI", Arial, sans-serif;
  background: var(--canvas);
  color: var(--ink);
}

* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; min-height: 100vh; background: var(--canvas); }
button, input, select { font: inherit; }
button { cursor: pointer; }
[hidden] { display: none !important; }

.login-shell { min-height: 100vh; display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(390px, .75fr); }
.login-brand { background: var(--ink); color: white; padding: clamp(28px, 5vw, 72px); display: flex; flex-direction: column; justify-content: space-between; min-height: 100vh; position: relative; overflow: hidden; }
.login-brand::after { content: ""; position: absolute; width: 72%; aspect-ratio: 1; right: -28%; top: 8%; border: 1px solid #ffffff26; border-radius: 50%; box-shadow: 0 0 0 80px #ffffff08, 0 0 0 160px #ffffff05; }
.brand-lockup { display: flex; gap: 13px; align-items: center; letter-spacing: .12em; position: relative; z-index: 1; }
.brand-lockup strong, .brand-lockup small { display: block; }
.brand-lockup strong { font-size: 17px; line-height: 1; }
.brand-lockup small { font-size: 8px; margin-top: 5px; letter-spacing: .28em; opacity: .66; }
.brand-lockup--sportex { width: fit-content; display: grid; gap: 4px; align-items: start; }
.sportex-logo-frame { position: relative; width: 174px; height: 25px; display: block; overflow: hidden; flex: 0 0 auto; }
.sportex-logo { position: absolute; top: -36px; left: -29px; display: block; width: 225px; max-width: none; height: auto; }
.sportex-logo-frame--login { width: 236px; height: 32px; }
.sportex-logo-frame--login .sportex-logo { top: -50px; left: -40px; width: 307px; }
.brand-product-label { color: #aab4ac; font: 700 8px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .28em; }
.brand-lockup--light { color: white; }
.login-thesis { max-width: 760px; position: relative; z-index: 1; }
.eyebrow, .section-code { font: 700 11px/1 "Arial Narrow", "Segoe UI", sans-serif; letter-spacing: .18em; text-transform: uppercase; color: var(--blue); }
.login-thesis .eyebrow { color: var(--signal); }
.login-thesis h1 { margin: 18px 0 24px; font: 900 clamp(62px, 8vw, 126px)/.78 "Arial Narrow", "Segoe UI", sans-serif; letter-spacing: -.055em; text-transform: uppercase; }
.login-thesis p { max-width: 590px; margin: 0; font-size: clamp(16px, 1.4vw, 21px); line-height: 1.55; color: #d7dad4; }
.route-line { position: relative; z-index: 1; display: grid; grid-template-columns: repeat(5, 1fr); list-style: none; padding: 0; margin: 64px 0 0; border-top: 1px solid #ffffff3b; }
.route-line li { padding-top: 15px; color: #919790; text-transform: uppercase; letter-spacing: .11em; font-size: 10px; }
.route-line li::before { content: ""; display: block; width: 7px; height: 7px; background: #6d736d; margin-top: -19px; margin-bottom: 13px; border-radius: 50%; }
.route-line li.is-active { color: white; }
.route-line li.is-active::before { width: 44%; height: 5px; border-radius: 0; background: var(--signal); }
.login-panel { background: var(--paper); display: grid; place-items: center; padding: 42px; }
.login-form { width: min(410px, 100%); display: grid; gap: 20px; }
.login-form h2, .sheet-head h2, .password-dialog h2 { margin: 9px 0 7px; font: 800 38px/1 "Arial Narrow", "Segoe UI", sans-serif; letter-spacing: -.035em; text-transform: uppercase; }
.login-form p { margin: 0; color: var(--muted); }
label { display: grid; gap: 8px; color: var(--ink-soft); font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; }
input, select { width: 100%; border: 1px solid var(--line); background: white; padding: 13px 14px; min-height: 48px; outline: none; border-radius: 0; color: var(--ink); }
input:focus, select:focus, button:focus-visible { border-color: var(--blue); box-shadow: 0 0 0 3px rgb(39 103 255 / 18%); outline: none; }
.button { min-height: 46px; border: 1px solid transparent; padding: 0 19px; font-weight: 800; font-size: 12px; text-transform: uppercase; letter-spacing: .075em; transition: transform .15s ease, background .15s ease; }
.button:hover { transform: translateY(-1px); }
.button:disabled { opacity: .5; cursor: wait; transform: none; }
.button--primary { color: #18221c; background: var(--signal); border-color: var(--signal); }
.button--signal { color: #18221c; background: var(--signal); border-color: var(--signal); }
.button--outline { color: var(--ink); background: transparent; border-color: var(--line-dark); }
.button--full { width: 100%; }
.form-error { min-height: 18px; margin: 0; color: var(--danger) !important; font-size: 13px; text-transform: none; letter-spacing: 0; }
.environment-note { color: var(--muted); line-height: 1.45; }

.app-shell { min-height: 100vh; display: grid; grid-template-columns: 224px 1fr; }
.sidebar { background: var(--ink); color: white; padding: 28px 22px 22px; display: flex; flex-direction: column; position: sticky; height: 100vh; top: 0; }
.side-nav { margin-top: 70px; display: grid; gap: 7px; }
.nav-item { width: 100%; border: 0; border-left: 3px solid transparent; background: transparent; color: #8e958e; padding: 13px 12px; display: flex; justify-content: space-between; text-align: left; font-weight: 700; }
.nav-item b { min-width: 24px; font-size: 10px; padding: 3px 7px; text-align: center; background: #ffffff12; }
.nav-item.is-active { color: white; border-left-color: var(--signal); background: #ffffff0d; }
.sidebar-foot { margin-top: auto; border-top: 1px solid #ffffff1c; padding-top: 18px; display: grid; gap: 12px; }
.sidebar-foot > span { color: #7f867f; font: 700 9px/1 monospace; letter-spacing: .12em; overflow: hidden; text-overflow: ellipsis; }
.text-button { color: white; border: 0; padding: 0; background: transparent; text-align: left; font-size: 12px; }
.workspace { min-width: 0; }
.topbar { height: 82px; padding: 0 clamp(20px, 4vw, 58px); background: var(--paper); border-bottom: 1px solid var(--line); display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.topbar strong { display: block; margin-top: 5px; }
.topbar-actions { display: flex; align-items: center; gap: 14px; }
.replay-actions { display: flex; align-items: center; gap: 9px; }
.account-button { display: flex; gap: 9px; align-items: center; border: 0; background: transparent; color: var(--ink); text-align: left; }
.account-button > span { width: 34px; height: 34px; display: grid; place-items: center; background: var(--ink); color: white; font-weight: 800; font-size: 11px; }
.account-button small { max-width: 180px; overflow: hidden; text-overflow: ellipsis; }
.production-track { height: 52px; padding: 0 clamp(20px, 4vw, 58px); background: white; display: grid; grid-template-columns: repeat(5, 1fr); border-bottom: 1px solid var(--line); }
.production-track span { display: flex; align-items: center; gap: 10px; border-right: 1px solid var(--line); padding: 0 13px; font: 700 10px/1 "Arial Narrow", sans-serif; text-transform: uppercase; letter-spacing: .08em; color: #858b84; }
.production-track span:first-child { border-left: 1px solid var(--line); }
.production-track b { font: 500 9px/1 monospace; }
.production-track .is-active { background: var(--ink); color: white; box-shadow: inset 0 -4px var(--signal); }
.content { padding: clamp(30px, 4vw, 62px); }
.view-header { display: grid; grid-template-columns: 1fr minmax(240px, 430px); gap: 40px; align-items: end; margin-bottom: 34px; }
.view-header h1 { margin: 9px 0 0; font: 900 clamp(42px, 5vw, 76px)/.9 "Arial Narrow", "Segoe UI", sans-serif; text-transform: uppercase; letter-spacing: -.045em; }
.view-header p { margin: 0; color: var(--muted); line-height: 1.55; }
.metrics-strip { display: grid; grid-template-columns: repeat(4, 1fr); background: var(--ink); color: white; margin-bottom: 20px; }
.metrics-strip article { min-height: 110px; padding: 23px; border-right: 1px solid #ffffff24; display: grid; align-content: space-between; }
.metrics-strip span { color: #9ba19b; font-size: 10px; text-transform: uppercase; letter-spacing: .09em; }
.metrics-strip strong { font: 800 27px/1 "Arial Narrow", sans-serif; letter-spacing: -.02em; }
.commercial-header h1 { max-width: 820px; font-family: "Bahnschrift Condensed", "Arial Narrow", sans-serif; }
.commercial-intro { display: grid; gap: 13px; justify-items: start; }
.local-proof { display: inline-flex; align-items: center; min-height: 29px; padding: 0 10px; background: var(--signal); color: var(--ink); font: 800 9px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .08em; }
.metrics-strip--commercial article:first-child { box-shadow: inset 0 4px var(--signal); }
.metrics-strip--commercial article:nth-child(2) { box-shadow: inset 0 4px var(--blue); }
.metrics-strip--commercial article:nth-child(3) { box-shadow: inset 0 4px #f2a93b; }
.commercial-list { display: grid; gap: 16px; }
.commercial-card { display: grid; grid-template-columns: 78px minmax(0, 1.2fr) minmax(260px, .8fr); min-height: 226px; background: var(--paper); border: 1px solid var(--line); position: relative; overflow: hidden; }
.evidence-rail { display: grid; grid-template-rows: repeat(3, 1fr); justify-items: center; background: var(--ink); color: white; padding: 18px 0; position: relative; }
.evidence-rail::before { content: ""; position: absolute; top: 35px; bottom: 35px; left: 50%; border-left: 2px dashed #ffffff42; }
.evidence-node { width: 28px; height: 28px; display: grid; place-items: center; background: var(--ink); border: 1px solid #ffffff66; border-radius: 50%; z-index: 1; font: 700 9px/1 "Cascadia Mono", Consolas, monospace; }
.evidence-node.is-live { color: var(--ink); background: var(--signal); border-color: var(--signal); }
.conversation-pane { padding: 24px 27px; display: grid; align-content: space-between; gap: 22px; }
.conversation-meta { display: grid; align-content: start; justify-items: start; gap: 13px; min-width: 0; }
.conversation-meta strong { display: block; font: 800 23px/1 "Bahnschrift Condensed", "Arial Narrow", sans-serif; letter-spacing: -.015em; }
.conversation-meta small { display: block; margin-top: 6px; color: var(--muted); font: 700 9px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .06em; text-transform: uppercase; }
.attribution-chip { display: block; max-width: 100%; min-height: 30px; padding: 10px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; background: #e4e8ff; color: #174ac8; font: 800 9px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .06em; }
.attribution-chip.is-unknown { background: #f5e6ca; color: #75480b; }
.message-quote { margin: 0; padding: 17px 19px; background: white; border-left: 4px solid var(--blue); font: 500 16px/1.5 Aptos, "Segoe UI", sans-serif; }
.message-quote::before { content: "MENSAJE NORMALIZADO"; display: block; margin-bottom: 9px; color: var(--muted); font: 700 8px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .1em; }
.decision-pane { padding: 24px 27px; border-left: 1px solid var(--line); background: #eeefe9; display: grid; align-content: space-between; gap: 20px; }
.stage-lockup { display: grid; gap: 8px; }
.stage-lockup > span { color: var(--muted); font: 700 9px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .09em; text-transform: uppercase; }
.stage-lockup strong { font: 900 clamp(38px, 4vw, 58px)/.8 "Bahnschrift Condensed", "Arial Narrow", sans-serif; letter-spacing: -.045em; }
.next-action { border-top: 1px solid var(--line); padding-top: 16px; }
.next-action span { display: block; margin-bottom: 7px; color: var(--blue); font: 800 9px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .09em; text-transform: uppercase; }
.next-action strong { font-size: 14px; line-height: 1.35; }
.commercial-empty { min-height: 310px; display: grid; grid-template-columns: 170px minmax(0, 1fr) auto; align-items: center; gap: 35px; padding: 42px; background: var(--paper); border: 1px solid var(--line); }
.commercial-empty h2 { margin: 10px 0 12px; max-width: 650px; font: 900 clamp(34px, 4.2vw, 62px)/.88 "Bahnschrift Condensed", "Arial Narrow", sans-serif; letter-spacing: -.04em; text-transform: uppercase; }
.commercial-empty p { max-width: 690px; margin: 0; color: var(--muted); line-height: 1.55; }
.evidence-spool { width: 150px; height: 150px; border: 16px solid var(--ink); border-radius: 50%; display: grid; place-items: center; position: relative; }
.evidence-spool::before { content: ""; position: absolute; inset: 25px; border: 2px dashed var(--line-dark); border-radius: 50%; }
.evidence-spool span { position: absolute; width: 8px; height: 8px; background: var(--signal); border-radius: 50%; }
.evidence-spool span:nth-child(1) { top: 7px; }
.evidence-spool span:nth-child(2) { right: 12px; bottom: 24px; }
.evidence-spool span:nth-child(3) { left: 8px; bottom: 35px; }
.empty-actions { display: grid; gap: 10px; min-width: 235px; }
.ledger { background: var(--paper); border: 1px solid var(--line); }
.order-board-shell { overflow-x: auto; border: 1px solid var(--line); background: var(--paper); }
.orders-view-switch { display: flex; justify-content: flex-end; gap: 6px; margin: 14px 0 8px; }
.orders-view-switch [aria-pressed="true"] { background: var(--surface-strong); color: var(--text-on-strong); }
.orders-sheet { min-width: 860px; }
.orders-sheet table { width: 100%; border-collapse: collapse; font-size: 13px; }
.orders-sheet th { padding: 12px 14px; text-align: left; background: var(--surface-strong); color: var(--text-on-strong); font: 800 9px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .07em; text-transform: uppercase; }
.orders-sheet td { padding: 12px 14px; border-bottom: 1px solid var(--line); white-space: nowrap; }
.orders-sheet tbody tr:hover { background: color-mix(in srgb, var(--blue) 7%, transparent); }
.orders-board { display: grid; grid-template-columns: repeat(5, minmax(218px, 1fr)); min-width: 1090px; align-items: start; }
.order-column { min-height: 320px; border-right: 1px solid var(--line); }
.order-column:last-child { border-right: 0; }
.order-column-head { display: flex; justify-content: space-between; align-items: center; padding: 13px 14px; border-bottom: 1px solid var(--line); font: 800 9px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .07em; text-transform: uppercase; }
.order-column-head strong { display: grid; min-width: 23px; height: 23px; place-items: center; border-radius: 999px; background: color-mix(in srgb, var(--blue) 14%, transparent); color: var(--ink); }
.order-card-stack { display: grid; gap: 10px; padding: 10px; }
