.creative-preview::before { content: "SPORTEX / AD"; align-self: start; margin-bottom: 42px; color: var(--creative-accent); font: 900 34px/.8 "Bahnschrift Condensed", "Arial Narrow", sans-serif; letter-spacing: -.04em; }
.creative-preview .creative-format { width: fit-content; padding: 5px 7px; background: var(--creative-accent); color: var(--ink); font: 800 8px/1 "Cascadia Mono", Consolas, monospace; }
.creative-preview > b { color: #aeb4ad; font: 700 8px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .08em; }
.creative-preview > strong { font: 900 28px/.9 "Bahnschrift Condensed", "Arial Narrow", sans-serif; text-transform: uppercase; }
.creative-preview p { margin: 0; color: #c6cbc5; font-size: 11px; line-height: 1.4; }
.origin-metadata { display: grid; grid-template-columns: 88px 1fr; margin: 0; padding: 10px 18px 18px; }
.origin-metadata dt, .origin-metadata dd { margin: 0; padding: 9px 0; border-bottom: 1px solid var(--line); overflow-wrap: anywhere; font-size: 10px; }
.origin-metadata dt { color: var(--muted); }
.origin-metadata dd { font-weight: 700; }
.unknown-origin { min-height: 190px; display: grid; place-items: center; align-content: center; gap: 14px; padding: 28px; text-align: center; }
.unknown-origin strong { padding: 10px; border: 1px solid #a36a18; color: #75480b; font: 900 15px/1 "Cascadia Mono", Consolas, monospace; }
.unknown-origin p { max-width: 260px; margin: 0; color: var(--muted); font-size: 12px; line-height: 1.5; }
.command-form { display: grid; gap: 13px; padding: 17px; }
.command-field { gap: 7px; font-size: 9px; }
.command-field input, .command-field select { min-height: 42px; padding: 9px 11px; }
.command-help { margin: -2px 0 0; color: var(--muted); font-size: 10px; line-height: 1.4; }
.button--full { width: 100%; }
.lead-detail-empty { min-height: 620px; display: grid; place-items: center; align-content: center; gap: 9px; text-align: center; }
.lead-detail-empty h2, .lead-detail-empty p { margin: 0; }
.lead-detail-empty p { color: var(--muted); }
.reset-dialog { width: min(520px, calc(100vw - 28px)); border-top: 8px solid var(--signal); padding: 28px; }
.reset-dialog form { display: grid; gap: 16px; }
.reset-dialog h2 { margin: 0; font: 900 34px/.95 "Bahnschrift Condensed", "Arial Narrow", sans-serif; text-transform: uppercase; }
.reset-dialog p { margin: 0; color: var(--muted); line-height: 1.45; }
.reset-dialog .sheet-actions { margin: 4px -28px -28px; }
.confirmation-check { grid-template-columns: auto 1fr; align-items: start; padding: 14px; border: 1px solid var(--line); background: white; text-transform: none; letter-spacing: 0; line-height: 1.4; }
.confirmation-check input { width: 18px; min-height: 18px; margin: 1px 0 0; padding: 0; }

@media (max-width: 1180px) {
  .crm-filterbar { grid-template-columns: 1.5fr repeat(3, 1fr); }
  .crm-clear { grid-column: 4; }
  .crm-workspace { grid-template-columns: 310px minmax(0, 1fr); }
  .lead-detail-grid { grid-template-columns: 1fr; }
  .detail-side { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .detail-side > .detail-card { align-self: start; }
  .command-stack { grid-column: 1 / -1; grid-template-columns: repeat(3, minmax(0, 1fr)); }
}

@media (max-width: 820px) {
  .stage-board { grid-template-columns: repeat(6, minmax(145px, 1fr)); overflow-x: auto; scroll-snap-type: x proximity; }
  .stage-station { scroll-snap-align: start; }
  .crm-filterbar { grid-template-columns: 1fr 1fr; }
  .crm-search { grid-column: 1 / -1; }
  .crm-clear { grid-column: 2; }
  .crm-workspace { grid-template-columns: 280px minmax(0, 1fr); }
  .brief-grid { grid-template-columns: 1fr 1fr; }
  .brief-fact:nth-child(3n) { border-right: 1px solid var(--line); }
  .brief-fact:nth-child(2n) { border-right: 0; }
  .qualification-grid, .detail-side, .command-stack { grid-template-columns: 1fr; }
  .qualification-column + .qualification-column { border-left: 0; border-top: 1px solid var(--line); }
  .command-stack { grid-column: auto; }
}

@media (max-width: 650px) {
  .commercial-header h1 { font-size: 43px; }
  .metrics-strip--commercial { margin-bottom: 14px; }
  .stage-board { margin: 0 -16px 14px; border-left: 0; border-right: 0; }
  .stage-station { min-width: 144px; min-height: 82px; padding: 13px; }
  .crm-filterbar { grid-template-columns: 1fr; padding: 13px; }
  .crm-search, .crm-clear { grid-column: 1; }
  .crm-clear { width: 100%; }
  .crm-workspace { display: block; }
  .lead-master { position: static; min-height: 580px; max-height: none; }
  .lead-list { max-height: none; overflow: visible; }
  .lead-detail { display: none; border-left: 0; border-right: 0; margin: 0 -16px; }
  .crm-workspace.is-detail-open .lead-master { display: none; }
  .crm-workspace.is-detail-open .lead-detail { display: block; }
  .lead-detail-head { grid-template-columns: 1fr; gap: 17px; padding: 18px 17px 22px; }
  .mobile-back { display: inline-flex; width: fit-content; min-height: 42px; align-items: center; padding: 0 12px; border: 1px solid #ffffff45; background: transparent; color: white; }
  .lead-title h2 { font-size: 43px; }
  .lead-status-lockup { padding: 16px 0 0; border-left: 0; border-top: 1px solid #ffffff2e; }
  .lead-detail-grid { padding: 10px; }
  .brief-grid { grid-template-columns: 1fr 1fr; }
  .brief-fact { min-height: 74px; padding: 13px; }
  .message-row { width: 90%; }
  .activity-row { grid-template-columns: 12px 1fr auto; }
  .activity-row p { grid-column: 2 / -1; }
  .detail-card-head { padding: 14px; }
  .reset-dialog { padding: 22px; }
  .reset-dialog .sheet-actions { margin: 2px -22px -22px; display: grid; }
}
@media (max-width: 650px) {
  #local-demo-actions { display: flex !important; }
  #local-demo-actions .button { min-height: 36px; padding: 0 9px; font-size: 8px; }
  .stage-station { min-width: 160px; }
}

/* TASK-20260803-005 · experiencia comercial aprobada */
:root {
  --ink: #18221c;
  --ink-soft: #344039;
  --paper: #ffffff;
  --canvas: #ffffff;
  --line: #d6dbd3;
  --line-dark: #9ca69e;
  --blue: #2457d6;
  --signal: #cfe64e;
  --danger: #bf4335;
  --success: #2f7a57;
  --muted: #68736c;
  --shadow: 0 22px 55px rgb(24 34 28 / 16%);
}

/* El login conserva la firma SPORTEX en ambos temas; no invierte grafito y blanco. */
.login-shell { background: #101612; }
.login-brand { background: #18221c; color: #ffffff; }
