.login-panel .environment-note { color: #9aa69e; }
.login-panel input { background: #18211b; border-color: #39443c; color: #ffffff; }

.button { min-height: 40px; border-radius: 8px; padding: 0 15px; font-size: 11px; text-transform: none; letter-spacing: 0; }
.button--primary { background: var(--blue); }
.button--quiet { color: var(--ink); background: #f5f7f3; border-color: var(--line); }
