.app-shell { grid-template-columns: 248px minmax(0, 1fr); background: var(--canvas); }
.sidebar { width: auto; height: 100vh; padding: 20px 16px 16px; overflow-y: auto; background: var(--ink); z-index: 15; }
.sidebar-brand { display: flex; align-items: center; justify-content: space-between; }
.sidebar-close { display: none; }
.side-nav { margin-top: 28px; gap: 3px; }
.nav-group-label { margin: 23px 10px 7px; color: #879188; font: 700 9px/1 "Cascadia Mono", Consolas, monospace; letter-spacing: .12em; text-transform: uppercase; }
