.nav-item { min-height: 39px; padding: 9px 10px; border: 0; border-radius: 7px; color: #bac2bb; font-size: 12px; font-weight: 600; }
.nav-item:hover { color: white; background: #ffffff0b; }
.nav-item.is-active { border: 0; color: white; background: #ffffff12; box-shadow: inset 3px 0 var(--signal); }
.nav-item b { border-radius: 999px; background: #ffffff16; }
.sidebar-foot { position: static; }
.workspace { min-width: 0; }
.topbar { position: sticky; top: 0; z-index: 10; height: 66px; padding: 0 24px; background: rgb(255 255 255 / 94%); backdrop-filter: blur(12px); }
.topbar-title { display: grid; gap: 2px; }
.topbar-title span { color: var(--muted); font-size: 10px; }
.topbar-title strong { margin: 0; font: 700 17px/1.2 "Bahnschrift SemiCondensed", "Segoe UI", sans-serif; }
.mobile-menu-button { display: none; width: 40px; height: 40px; border: 1px solid var(--line); border-radius: 8px; background: white; }
.content { padding: 24px; }
.page-intro { display: flex; justify-content: space-between; align-items: end; gap: 28px; margin-bottom: 20px; }
.page-intro > div { min-width: 0; }
.page-intro h1 { margin: 4px 0 0; font: 750 clamp(28px, 3vw, 40px)/1 "Bahnschrift SemiCondensed", "Segoe UI", sans-serif; letter-spacing: -.025em; }
.page-intro p { max-width: 520px; margin: 0; color: var(--muted); font-size: 13px; line-height: 1.5; }
.page-intro--compact { margin-bottom: 14px; }
.page-kicker { color: var(--blue); font: 700 9px/1.2 "Cascadia Mono", Consolas, monospace; letter-spacing: .09em; text-transform: uppercase; }

.today-metrics { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 14px; }
.today-metrics button { min-height: 118px; display: grid; grid-template-columns: 1fr auto; grid-template-rows: auto 1fr; gap: 10px; padding: 17px; border: 1px solid var(--line); border-radius: 10px; background: var(--paper); color: var(--ink); text-align: left; }
.today-metrics button:hover, .today-metrics button.is-selected { border-color: var(--blue); box-shadow: 0 0 0 2px rgb(36 87 214 / 10%); }
.today-metrics span { font-size: 12px; font-weight: 700; }
.today-metrics strong { grid-row: 1 / 3; grid-column: 2; font: 750 32px/1 "Bahnschrift SemiCondensed", "Segoe UI", sans-serif; color: var(--blue); }
.today-metrics small { align-self: end; color: var(--muted); font-size: 10px; line-height: 1.35; }
.today-board { overflow: hidden; border: 1px solid var(--line); border-radius: 11px; background: var(--paper); }
.today-board > header { min-height: 64px; display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 12px 18px; border-bottom: 1px solid var(--line); }
.today-board h2 { margin: 4px 0 0; font-size: 18px; }
.today-board > header > span { color: var(--muted); font-size: 11px; }
.today-list { display: grid; }
.today-row { display: grid; grid-template-columns: minmax(150px, .75fr) minmax(180px, 1fr) minmax(240px, 1.45fr) auto; gap: 20px; align-items: center; min-height: 82px; padding: 14px 18px; border-bottom: 1px solid var(--line); }
.today-row:last-child { border-bottom: 0; }
.today-row:hover { background: #f8faf7; }
.today-flag, .today-identity, .today-next { display: grid; gap: 5px; min-width: 0; }
.today-flag > span { width: fit-content; padding: 5px 8px; border-radius: 999px; background: #e8eefc; color: #1d4bbd; font-size: 9px; font-weight: 800; }
.today-row[data-priority="overdue"] .today-flag > span { background: #f8e5e2; color: var(--danger); }
.today-row[data-priority="waiting"] .today-flag > span { background: #edf0eb; color: #566159; }
.today-row[data-priority="decision"] .today-flag > span { background: #e5f2e9; color: var(--success); }
.today-flag small, .today-identity span { overflow: hidden; color: var(--muted); font-size: 10px; text-overflow: ellipsis; white-space: nowrap; }
.today-identity strong, .today-next strong { overflow: hidden; font-size: 12px; line-height: 1.35; text-overflow: ellipsis; }
.today-next span { color: var(--blue); font-size: 9px; font-weight: 800; text-transform: uppercase; }
.today-empty { min-height: 230px; display: grid; place-items: center; align-content: center; gap: 8px; padding: 30px; text-align: center; }
.today-empty p { margin: 0; color: var(--muted); }

.crm-filterbar { grid-template-columns: minmax(210px, 1.5fr) repeat(3, minmax(125px, .7fr)) auto; gap: 9px; margin-bottom: 10px; padding: 10px; border-radius: 10px; }
.crm-filterbar label { text-transform: none; letter-spacing: 0; }
.crm-filterbar input, .crm-filterbar select { min-height: 38px; border-radius: 7px; }
.crm-workspace { grid-template-columns: 300px minmax(0, 1fr); gap: 10px; height: calc(100vh - 280px); min-height: 540px; }
.lead-master { position: static; min-height: 0; max-height: none; height: 100%; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; }
.lead-master-head { min-height: 58px; padding: 11px 13px; border: 0; background: var(--ink); }
.lead-master-head > div { gap: 3px; }
.lead-master-head span { font-size: 10px; }
.lead-master-head strong { color: #c8d0c9; font-size: 10px; font-weight: 500; }
.persistence-chip { border-radius: 999px; font-size: 7px; }
.lead-list { overflow-y: auto; }
.lead-row { gap: 9px; padding: 13px 12px 13px 15px; }
.lead-row::before { width: 3px; background: #aeb6af; }
.lead-row[data-priority="response"]::before { background: var(--blue); }
.lead-row[data-priority="overdue"]::before { background: var(--danger); }
.lead-row[data-priority="waiting"]::before { background: #7e8a81; }
.lead-row[data-priority="decision"]::before { background: var(--success); }
.lead-row.is-selected { box-shadow: inset -3px 0 var(--blue); }
.lead-row-identity strong { font-size: 12px; }
.lead-row-identity small { font-size: 10px; }
.lead-priority { flex: none; max-width: 104px; padding: 5px 7px; border-radius: 999px; background: #edf0eb; color: var(--ink-soft); font-size: 8px; font-weight: 800; }
.lead-row-meta { font-size: 9px; }
.lead-row-next { padding-top: 8px; font-size: 10px; }

.lead-detail { min-height: 0; height: 100%; border: 1px solid var(--line); border-radius: 10px; overflow: hidden; background: var(--paper); }
.lead-mobile-tabs { display: none; }
.lead-focus { height: 100%; min-height: 0; overflow: hidden; display: grid; grid-template-columns: minmax(380px, 1fr) 330px; }
.lead-chat-pane { min-width: 0; min-height: 0; max-height: 100%; height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; background: var(--paper); }
.lead-focus-head { min-height: 72px; display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 12px 15px; border-bottom: 1px solid var(--line); background: white; }
.lead-focus-head h2 { margin: 3px 0; font: 750 22px/1 "Bahnschrift SemiCondensed", "Segoe UI", sans-serif; }
.lead-focus-head p { margin: 0; color: var(--muted); font-size: 10px; }
.lead-conversation { min-height: 0; overflow-y: auto; align-content: start; padding: 16px; }
.message-row { width: min(82%, 560px); border-radius: 11px; padding: 11px 13px; box-shadow: 0 2px 7px rgb(24 34 28 / 5%); }
.message-row.is-delta { border-color: #c9d4f2; background: #eaf0ff; }
.message-row p { font-size: 12px; }
.draft-area { padding: 12px; border-top: 1px solid var(--line); background: white; }
.draft-area > header { display: flex; justify-content: space-between; gap: 12px; margin-bottom: 8px; }
.draft-area > header small { color: var(--muted); font-size: 9px; }
.draft-input { min-height: 68px; max-height: 110px; border-radius: 8px; padding: 10px 11px; font-size: 12px; }
.draft-actions { display: flex; gap: 7px; margin-top: 8px; }
