.draft-resource span, .draft-resource small { color: #3d5c49; font-size: 9px; }
.lead-work-pane { min-width: 0; min-height: 0; max-height: 100%; height: 100%; overflow-y: auto; border-left: 1px solid var(--line); background: white; }
.work-head { min-height: 57px; display: flex; justify-content: space-between; align-items: center; padding: 11px 14px; border-bottom: 1px solid var(--line); }
.work-head strong { color: var(--muted); font-size: 9px; }
.work-section { padding: 13px 14px; border-bottom: 1px solid var(--line); }
.work-section h3 { margin: 0 0 9px; font-size: 10px; text-transform: uppercase; letter-spacing: .07em; }
.inline-command { display: grid; grid-template-columns: 1fr auto; gap: 7px; }
.inline-command select, .work-action-form input, .work-followup-form select { min-height: 37px; padding: 8px 9px; border-radius: 7px; }
.work-summary, .work-suggestion p { margin: 0; color: var(--ink-soft); font-size: 11px; line-height: 1.45; }
.fact-chips { display: flex; flex-wrap: wrap; gap: 5px; }
.fact-chips span { padding: 6px 7px; border-radius: 6px; background: #edf5ef; color: #315d43; font-size: 9px; }
.work-missing ul { margin: 0; padding-left: 17px; color: #7b4a20; font-size: 10px; line-height: 1.55; }
.work-complete { margin: 0; color: var(--success); font-size: 10px; }
.work-action { background: #f4f7ff; box-shadow: inset 3px 0 var(--blue); }
.work-action-form { display: grid; gap: 7px; }
.work-action-form textarea { min-height: 68px; border-radius: 7px; padding: 9px; font-size: 11px; }
.work-suggestion { background: #f8f9f6; }
.work-origin { display: grid; gap: 5px; }
.work-origin h3 { margin-bottom: 3px; }
.work-origin strong { font-size: 11px; }
.work-origin small { color: var(--muted); font-size: 9px; }
.work-followup { border-bottom: 1px solid var(--line); }
.work-followup summary { padding: 13px 14px; font-size: 10px; font-weight: 800; cursor: pointer; }
.work-followup-form { display: grid; gap: 7px; padding: 0 14px 14px; }
.work-followup textarea { min-height: 65px; border-radius: 7px; font-size: 11px; }
.lead-detail-empty { min-height: 100%; }

.lead-sheet-dialog { width: min(980px, calc(100vw - 28px)); max-height: calc(100vh - 28px); border-radius: 12px; overflow: auto; }
.lead-sheet-head { position: sticky; top: 0; z-index: 2; display: flex; justify-content: space-between; align-items: start; gap: 20px; padding: 18px 20px; background: var(--surface-strong); color: var(--text-on-strong); }
.lead-sheet-head h2 { margin: 5px 0; font: 750 28px/1 "Bahnschrift SemiCondensed", "Segoe UI", sans-serif; }
.lead-sheet-head p { margin: 0; color: #bdc6be; font-size: 11px; }
.lead-sheet-body { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; padding: 12px; }
