/* Leads administra oportunidades; WhatsApp conserva el chat completo. */
#commercial-view .crm-workspace { display: block; height: auto; min-height: 0; }
#commercial-view .lead-master { display: block; height: auto; min-height: 0; max-height: none; overflow: visible; }
#commercial-view .lead-list { overflow-x: auto; overflow-y: visible; overscroll-behavior-inline: contain; }
