.lead-kanban-card { min-width: 0; }
.lead-kanban-preview { overflow: hidden; padding-top: 7px; border-top: 1px solid var(--line); color: var(--muted); font-size: 9px; line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }
.lead-sheet-actions { display: flex; align-items: center; gap: 8px; }
