:root[data-theme="dark"] .lead-message-preview-row.is-delta time { color: #c7d8c7; }

.candidate-panel, .settings-reset, .results-panel { margin-top: 16px; padding: 18px; border: 1px solid var(--line); border-radius: 10px; background: white; }
.candidate-panel header h2, .settings-reset h2, .results-panel h2 { margin: 5px 0 13px; font-size: 18px; }
.candidate-list { display: grid; gap: 8px; }
.candidate-row { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 12px; border: 1px solid var(--line); border-radius: 8px; }
.candidate-row > div { display: grid; gap: 3px; }
.candidate-row span, .candidate-row small { color: var(--muted); font-size: 10px; }
.module-content { display: grid; gap: 14px; }
.module-grid, .results-metrics, .playbook-list { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.results-metrics { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.module-card { min-height: 145px; display: grid; align-content: space-between; gap: 12px; padding: 18px; border: 1px solid var(--line); border-radius: 10px; background: white; }
.module-card h2 { margin: 0; font-size: 17px; }
.module-card p { margin: 0; color: var(--ink-soft); font-size: 12px; line-height: 1.45; }
.module-card small { color: var(--muted); font-size: 10px; }
.results-metrics .module-card p { color: var(--blue); font: 750 31px/1 "Bahnschrift SemiCondensed", "Segoe UI", sans-serif; }
.results-panel { margin-top: 0; }
.result-row { display: flex; justify-content: space-between; gap: 20px; padding: 11px 0; border-top: 1px solid var(--line); font-size: 11px; }
.result-row span { color: var(--muted); }
