.creative-module-card { min-height: 230px; display: grid; align-content: end; gap: 8px; padding: 20px; border-top: 8px solid var(--creative-color); border-radius: 8px; background: var(--surface-strong); color: var(--text-on-strong); }
.creative-module-card > span, .creative-module-card small { color: var(--creative-color); font-size: 9px; font-weight: 800; }
.creative-module-card h2 { margin: 0; font: 750 24px/1 "Bahnschrift SemiCondensed", "Segoe UI", sans-serif; }
.creative-module-card p { margin: 0; color: #c8d0c9; font-size: 11px; line-height: 1.45; }
.settings-reset p { color: var(--muted); }
.stage-board { border-radius: 8px; overflow: auto; }
.stage-station { min-width: 130px; }
.sidebar-scrim { position: fixed; inset: 0; z-index: 14; background: rgb(24 34 28 / 48%); }

@media (max-width: 1180px) {
  .app-shell { grid-template-columns: 220px minmax(0, 1fr); }
  .content { padding: 18px; }
  .crm-workspace { grid-template-columns: 275px minmax(0, 1fr); }
  .lead-focus { grid-template-columns: minmax(340px, 1fr) 300px; }
  .today-row { grid-template-columns: 145px minmax(160px, .8fr) minmax(220px, 1.2fr) auto; gap: 13px; }
}

@media (max-width: 900px) {
  .app-shell { display: block; }
  .sidebar { position: fixed; inset: 0 auto 0 0; width: 278px; height: 100vh; padding: 20px 16px; flex-direction: column; transform: translateX(-105%); transition: transform .2s ease; }
  .sidebar.is-open { transform: translateX(0); }
  .sidebar-brand { width: 100%; }
  .sidebar-close { display: grid; place-items: center; }
  .sidebar .brand-lockup > span:last-child, .nav-item span, .sidebar-foot .text-button { display: block; }
  .side-nav { width: 100%; margin-top: 28px; display: grid; }
  .nav-item { width: 100%; justify-content: space-between; border: 0; }
