  .sidebar-foot { display: grid; }
  .mobile-menu-button { display: block; }
  .topbar { justify-content: flex-start; }
  .topbar-actions { margin-left: auto; }
  body.menu-open { overflow: hidden; }
  .crm-workspace { grid-template-columns: 260px minmax(0, 1fr); }
  .lead-focus { grid-template-columns: 1fr 290px; }
  .today-metrics { grid-template-columns: 1fr 1fr; }
  .results-metrics { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 720px) {
  .topbar { min-height: 62px; height: 62px; padding: 0 12px; align-items: center; }
  .topbar-actions { flex-direction: row; align-items: center; }
  .account-button small, .replay-actions { display: none !important; }
  .content { padding: 14px 12px 22px; }
  .page-intro { align-items: start; margin-bottom: 14px; }
  .page-intro h1 { font-size: 30px; }
  .page-intro p { display: none; }
  .today-metrics { grid-template-columns: 1fr 1fr; gap: 7px; }
  .today-metrics button { min-height: 100px; padding: 13px; }
  .today-metrics strong { font-size: 27px; }
  .today-row { grid-template-columns: 1fr auto; gap: 9px 12px; padding: 13px; }
  .today-flag { grid-column: 1; }
  .today-identity { grid-column: 1; }
  .today-next { grid-column: 1 / -1; padding-top: 8px; border-top: 1px solid var(--line); }
  .today-row > .button { grid-column: 2; grid-row: 1 / 3; align-self: center; padding: 0 11px; font-size: 10px; }
  .crm-filterbar { grid-template-columns: 1fr 1fr; }
  .crm-search { grid-column: 1 / -1; }
  .crm-clear { grid-column: 2; }
  .crm-workspace { display: block; height: auto; min-height: 0; }
  .lead-master { min-height: calc(100vh - 235px); height: auto; }
  .lead-list { overflow: visible; }
  .lead-detail { display: none; height: calc(100vh - 144px); margin: 0; border-radius: 9px; }
  .crm-workspace.is-detail-open .lead-master { display: none; }
  .crm-workspace.is-detail-open .lead-detail { display: block; }
  .lead-mobile-tabs { height: 42px; display: grid; grid-template-columns: repeat(3, 1fr); border-bottom: 1px solid var(--line); background: white; }
  .lead-mobile-tabs button { border: 0; border-bottom: 3px solid transparent; background: transparent; font-size: 11px; font-weight: 700; }
  .lead-mobile-tabs button.is-active { border-bottom-color: var(--blue); color: var(--blue); }
  .lead-focus { height: calc(100% - 42px); display: block; }
  .lead-focus[data-mobile-tab="chat"] .lead-work-pane { display: none; }
  .lead-focus[data-mobile-tab="work"] .lead-chat-pane { display: none; }
  .lead-chat-pane, .lead-work-pane { height: 100%; }
  .lead-work-pane { border-left: 0; }
  .lead-focus-head { min-height: 64px; padding: 9px 11px; }
  .lead-focus-head h2 { font-size: 18px; }
  .lead-focus-head .button { display: none; }
  .mobile-back { display: inline-flex; min-height: 34px; padding: 0 8px; border-color: var(--line); border-radius: 7px; color: var(--ink); }
  .lead-conversation { padding: 10px; }
  .message-row { width: 91%; }
  .draft-area { padding: 9px; }
  .draft-actions { display: grid; grid-template-columns: 1fr 1fr; }
  .draft-actions .button:last-child { grid-column: 1 / -1; margin: 0; }
  .lead-sheet-body { grid-template-columns: 1fr; }
  .lead-sheet-actions .button { padding: 0 9px; font-size: 10px; }
  .lead-sheet-more-info[open] { grid-template-columns: 1fr; }
  .module-grid, .creative-module-grid, .playbook-list { grid-template-columns: 1fr; }
  .results-metrics { grid-template-columns: 1fr 1fr; }
  .candidate-row { align-items: start; }
  .ledger { overflow-x: auto; }
  .ledger-head, .ledger-row { min-width: 900px; }
  .ledger--clients .ledger-head, .ledger--clients .ledger-row { min-width: 650px; }
  .toast { left: 12px; right: 12px; bottom: 12px; }
}

@media (max-width: 430px) {
  .today-metrics button { min-height: 92px; }
  .today-metrics span { font-size: 10px; }
  .today-metrics small { font-size: 8px; }
  .today-board > header { padding: 11px 13px; }
  .today-row > .button { min-width: 74px; font-size: 9px; }
  .crm-filterbar { grid-template-columns: 1fr; }
  .crm-search, .crm-clear { grid-column: 1; }
  .results-metrics { grid-template-columns: 1fr; }
}

/* WhatsApp es una superficie operativa propia: conversación primero, contexto al lado. */
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
#local-demo-actions[hidden] { display: none !important; }
.whatsapp-intro { align-items: center; }
.sync-state { min-width: 250px; display: flex; align-items: center; gap: 10px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 9px; background: white; }
.sync-state > div { display: grid; gap: 2px; }
.sync-state strong { font-size: 11px; }
.sync-state small { color: var(--muted); font-size: 9px; }
.sync-dot { width: 9px; height: 9px; flex: 0 0 auto; border-radius: 50%; background: #d59b21; box-shadow: 0 0 0 4px rgb(213 155 33 / 13%); }
.whatsapp-workspace { height: calc(100vh - 178px); min-height: 570px; display: grid; grid-template-columns: 330px minmax(0, 1fr); overflow: hidden; border: 1px solid var(--line); border-radius: 11px; background: white; box-shadow: 0 18px 45px rgb(24 34 28 / 8%); }
.whatsapp-master { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); border-right: 1px solid var(--line); background: white; }
.whatsapp-master-head { display: grid; gap: 11px; padding: 14px; border-bottom: 1px solid var(--line); }
.whatsapp-master-head > div { display: flex; align-items: center; justify-content: space-between; }
.whatsapp-master-head strong { font-size: 13px; }
.whatsapp-master-head > div span { min-width: 24px; padding: 4px 7px; border-radius: 999px; background: #edf0eb; color: var(--muted); font-size: 9px; text-align: center; }
.whatsapp-search { text-transform: none; letter-spacing: 0; }
.whatsapp-search input { min-height: 39px; padding: 9px 11px; border-radius: 8px; background: var(--paper); font-size: 11px; }
.whatsapp-unread-filter { width: fit-content; padding: 6px 10px; border: 1px solid var(--line); border-radius: 999px; background: var(--surface); color: var(--muted); font-size: 10px; font-weight: 750; }
.whatsapp-unread-filter:hover, .whatsapp-unread-filter.is-active { border-color: var(--blue); background: var(--selected-bg); color: var(--selected-text); }
.whatsapp-list { min-height: 0; overflow-y: auto; }
.whatsapp-row { width: 100%; min-height: 94px; display: grid; grid-template-columns: 42px minmax(0, 1fr); gap: 11px; align-items: start; padding: 13px; border: 0; border-bottom: 1px solid #e6e9e3; background: white; color: var(--ink); text-align: left; }
.whatsapp-row:hover { background: #f7f9f5; }
.whatsapp-row.is-selected { background: #edf3ff; box-shadow: inset 3px 0 var(--blue); }
.whatsapp-row.is-closed { background: color-mix(in srgb, var(--paper) 92%, var(--canvas)); color: var(--muted); }
.whatsapp-row.is-closed .whatsapp-avatar { opacity: .62; filter: grayscale(.35); }
.whatsapp-row.is-closed .whatsapp-team,
.whatsapp-row.is-closed .whatsapp-preview { color: var(--muted); }
.whatsapp-row.is-closed:hover { background: color-mix(in srgb, var(--signal) 8%, var(--paper)); box-shadow: inset 3px 0 color-mix(in srgb, var(--muted) 70%, transparent); }
.whatsapp-closed-state { width: fit-content; padding: 2px 6px; border: 1px solid color-mix(in srgb, var(--muted) 45%, transparent); border-radius: 999px; color: var(--muted); font-size: 7px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; }
.whatsapp-row.is-unread .whatsapp-row-head strong, .whatsapp-row.is-unread .whatsapp-preview { color: var(--ink); font-weight: 800; }
.whatsapp-unread-badge { min-width: 18px; height: 18px; display: grid; place-items: center; margin-left: auto; padding: 0 5px; border-radius: 999px; background: #22a06b; color: white; font-size: 9px; font-weight: 900; }
.whatsapp-avatar { width: 42px; height: 42px; display: grid; place-items: center; border: 1px solid #b9c0ba; border-radius: 50%; background: var(--paper); color: var(--ink-soft); font-size: 11px; font-weight: 800; }
.whatsapp-avatar--detail { width: 40px; height: 40px; flex: 0 0 auto; border-color: #b8c8ef; background: #eaf0ff; color: #1f4db8; }
.whatsapp-row-copy { min-width: 0; display: grid; gap: 4px; }
.whatsapp-row-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.whatsapp-row-head strong { overflow: hidden; font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }
.whatsapp-row-head time { flex: none; color: var(--muted); font-size: 7px; }
.whatsapp-team { overflow: hidden; color: #315d43; font-size: 9px; font-weight: 700; text-overflow: ellipsis; white-space: nowrap; }
.whatsapp-preview { overflow: hidden; color: var(--muted); font-size: 9px; line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }
.whatsapp-stage { width: fit-content; margin-top: 2px; padding: 3px 6px; border-radius: 999px; background: #edf0eb; color: #566159; font-size: 7px; font-weight: 800; text-transform: uppercase; }
.whatsapp-detail { min-width: 0; min-height: 0; height: 100%; overflow: hidden; background: var(--paper); }
.whatsapp-mobile-tabs { display: none; }
.whatsapp-focus { height: 100%; grid-template-columns: minmax(400px, 1fr) 330px; }
.whatsapp-chat-head { justify-content: flex-start; }
.whatsapp-chat-head .button { margin-left: auto; }
.whatsapp-chat-identity { min-width: 0; display: grid; gap: 3px; }
.whatsapp-chat-identity h2 { margin: 0; overflow: hidden; font: 750 18px/1.1 "Bahnschrift SemiCondensed", "Segoe UI", sans-serif; text-overflow: ellipsis; white-space: nowrap; }
.whatsapp-chat-identity p { margin: 0; overflow: hidden; color: var(--muted); font-size: 9px; text-overflow: ellipsis; white-space: nowrap; }
.whatsapp-detail-empty, .whatsapp-empty { min-height: 100%; display: grid; place-items: center; align-content: center; gap: 8px; padding: 28px; text-align: center; }
.whatsapp-detail-empty h2, .whatsapp-empty strong { margin: 0; font-size: 18px; }
.whatsapp-detail-empty p, .whatsapp-empty p { max-width: 320px; margin: 0; color: var(--muted); font-size: 11px; line-height: 1.45; }
.whatsapp-empty-mark { width: 48px; height: 48px; display: grid; place-items: center; border-radius: 50%; background: var(--ink); color: var(--signal); font-size: 22px; }

/* Concepto WhatsApp primero: el producto ocupa el marco, la inteligencia no invade el chat. */
#whatsapp-view { height: 100%; }
#whatsapp-view .whatsapp-workspace { height: calc(100vh - 114px); min-height: 580px; border-radius: 4px; box-shadow: none; }
.whatsapp-row { min-height: 82px; }
.whatsapp-chat-pane { height: 100%; }
.whatsapp-chat-head { min-height: 64px; padding: 10px 14px; background: var(--paper); }
.whatsapp-chat-menu { width: 38px; height: 38px; margin-left: auto; border: 0; border-radius: 50%; background: transparent; color: var(--muted); font-size: 22px; line-height: 1; }
.whatsapp-chat-menu:hover { background: #e9ece7; color: var(--ink); }
.whatsapp-chat-pane .lead-conversation { padding: 22px 6%; background-color: var(--paper); background-image: radial-gradient(rgb(24 34 28 / 7%) .7px, transparent .7px); background-size: 14px 14px; }
.whatsapp-chat-pane .message-row { border: 0; border-radius: 8px; }
.whatsapp-chat-pane .message-row.is-client { background: white; }
.whatsapp-chat-pane .message-row.is-delta { background: #dcebd6; box-shadow: 0 2px 7px rgb(24 34 28 / 5%); }
.whatsapp-operational-event { justify-self: center; width: min(78%, 540px); display: grid; grid-template-columns: 22px minmax(0, 1fr) auto; gap: 9px; align-items: center; padding: 7px 10px; border: 1px solid color-mix(in srgb, var(--signal) 24%, var(--line)); border-radius: 999px; background: color-mix(in srgb, var(--paper) 92%, var(--signal)); color: var(--ink-soft); box-shadow: 0 2px 7px rgb(24 34 28 / 4%); }
.whatsapp-operational-mark { width: 20px; height: 20px; display: grid; place-items: center; border-radius: 50%; background: color-mix(in srgb, var(--signal) 24%, transparent); color: color-mix(in srgb, var(--signal) 62%, #203023); font-size: 11px; font-weight: 900; }
.whatsapp-operational-copy { min-width: 0; display: grid; gap: 2px; }
.whatsapp-operational-copy strong { overflow: hidden; font-size: 11px; line-height: 1.25; text-overflow: ellipsis; white-space: nowrap; }
.whatsapp-operational-copy small { overflow: hidden; color: var(--muted); font-size: 10px; line-height: 1.3; text-overflow: ellipsis; white-space: nowrap; }
.whatsapp-operational-event time { color: var(--muted); font-size: 9px; white-space: nowrap; }
.whatsapp-composer { position: relative; display: grid; grid-template-columns: 40px minmax(0, 1fr) 42px; gap: 9px; align-items: end; padding: 12px 14px; border-top: 1px solid var(--line); background: var(--paper); }
.whatsapp-image-preview { grid-column: 1 / -1; min-width: 0; display: grid; grid-template-columns: 54px minmax(0, 1fr) 30px; gap: 10px; align-items: center; padding: 8px; border: 1px solid var(--line); border-radius: 10px; background: var(--surface); color: var(--ink); font-size: 11px; }
.whatsapp-image-preview img { width: 54px; height: 54px; border-radius: 7px; object-fit: cover; }
.whatsapp-image-preview span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.whatsapp-image-remove { width: 28px; height: 28px; border: 0; border-radius: 50%; background: var(--surface-strong); color: var(--ink); font-size: 18px; }
.whatsapp-image-message { width: min(320px, 72vw); margin: 4px 0; display: grid; gap: 6px; }
.whatsapp-image-message:not(.is-loading) { cursor: zoom-in; }
.whatsapp-image-message img { width: 100%; max-height: 360px; border-radius: 7px; object-fit: cover; }
.whatsapp-image-message figcaption { font-size: 12px; line-height: 1.4; }
.whatsapp-image-loading { min-height: 110px; display: grid; place-items: center; border: 1px dashed var(--line); border-radius: 7px; color: var(--muted); font-size: 10px; }
.whatsapp-composer-icon, .whatsapp-send { width: 40px; height: 40px; display: grid; place-items: center; border: 0; border-radius: 50%; background: transparent; color: #657068; font-size: 24px; }
.whatsapp-send { width: 42px; height: 42px; background: var(--blue); color: white; font-size: 18px; }
.whatsapp-composer button:disabled { opacity: .46; cursor: default; }
.whatsapp-composer-input { min-height: 42px; max-height: 108px; resize: none; padding: 11px 16px; border: 1px solid #d9ddd7; border-radius: 22px; background: white; font-size: 12px; line-height: 1.45; }
.whatsapp-local-note { position: absolute; top: -21px; right: 14px; padding: 4px 8px; border: 1px solid var(--line); border-bottom: 0; border-radius: 7px 7px 0 0; background: var(--paper); color: var(--muted); font-size: 8px; }
.whatsapp-image-viewer { width: min(900px, calc(100vw - 32px)); max-width: none; padding: 0; border: 0; background: rgb(9 13 10 / 96%); }
.whatsapp-image-viewer::backdrop { background: rgb(0 0 0 / 72%); }
.whatsapp-image-viewer-body { min-height: min(680px, calc(100vh - 64px)); display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 12px; padding: 14px; }
.whatsapp-image-viewer-body .icon-button { justify-self: end; background: white; color: #172019; }
.whatsapp-image-viewer-body img { width: 100%; height: min(590px, calc(100vh - 170px)); object-fit: contain; }
.whatsapp-image-viewer-body .button { justify-self: center; }
.whatsapp-more-info { border-top: 1px solid var(--line); }
.whatsapp-more-info > summary { padding: 13px 2px; color: var(--ink-soft); cursor: pointer; font-size: 11px; font-weight: 800; }
.whatsapp-more-info[open] > summary { color: var(--blue); }

/* Ningún hijo puede ensanchar la pestaña completa: la lectura sucede dentro de cada panel. */
#whatsapp-view, .whatsapp-workspace, .whatsapp-detail, .whatsapp-detail-workspace,
.whatsapp-chat-pane, .whatsapp-inline-details, .whatsapp-inline-details-body,
.whatsapp-row-copy, .whatsapp-chat-identity { min-width: 0; max-width: 100%; }
#whatsapp-view { overflow-x: clip; }
.whatsapp-detail-workspace { overflow: hidden; }

@media (max-width: 1050px) {
  .whatsapp-workspace { grid-template-columns: 290px minmax(0, 1fr); }
  .whatsapp-focus { grid-template-columns: minmax(330px, 1fr) 290px; }
}

@media (max-width: 720px) {
  .whatsapp-intro { align-items: flex-start; }
  .sync-state { min-width: 0; width: auto; padding: 7px 9px; }
  .sync-state small { display: none; }
  #whatsapp-view .whatsapp-workspace { height: calc(100vh - 90px); min-height: 520px; display: block; border-radius: 0; }
  .whatsapp-master, .whatsapp-detail { height: 100%; }
  .whatsapp-detail { display: none; }
  .whatsapp-workspace.is-detail-open .whatsapp-master { display: none; }
  .whatsapp-workspace.is-detail-open .whatsapp-detail { display: block; }
  .whatsapp-chat-pane { height: 100%; }
  .whatsapp-chat-head { min-height: 62px; }
  .whatsapp-chat-head .whatsapp-avatar { display: none; }
  .whatsapp-chat-menu { flex: 0 0 auto; }
  .whatsapp-chat-pane .lead-conversation { padding: 12px 10px 30px; }
  .whatsapp-operational-event { width: min(94%, 480px); grid-template-columns: 20px minmax(0, 1fr); border-radius: 12px; }
  .whatsapp-operational-event time { grid-column: 2; }
  .whatsapp-composer { grid-template-columns: 36px minmax(0, 1fr) 40px; gap: 7px; padding: 9px; }
  .whatsapp-composer-icon { width: 36px; height: 40px; }
  .whatsapp-send { width: 40px; height: 40px; }
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --ink: #edf3ee;
  --ink-soft: #c3cec6;
  --paper: #171d19;
  --canvas: #0e1310;
  --line: #303a33;
  --line-dark: #68756c;
  --blue: #7698ff;
  --signal: #cee65a;
  --danger: #ff8175;
  --success: #69c996;
  --muted: #8e9b92;
  --shadow: 0 24px 70px rgb(0 0 0 / 42%);
}

:root[data-theme="dark"] body,
:root[data-theme="dark"] .workspace,
:root[data-theme="dark"] .content { background: var(--canvas); color: var(--ink); }
:root[data-theme="dark"] .topbar { background: rgb(23 29 25 / 95%); }
:root[data-theme="dark"] .sidebar { background: #101612; }
:root[data-theme="dark"] .account-button > span,
:root[data-theme="dark"] .whatsapp-empty-mark { background: #2b352e; color: var(--signal); }
:root[data-theme="dark"] input,
:root[data-theme="dark"] select,
:root[data-theme="dark"] textarea,
:root[data-theme="dark"] dialog { background: #1d241f; color: var(--ink); border-color: var(--line); }
:root[data-theme="dark"] input::placeholder,
:root[data-theme="dark"] textarea::placeholder { color: #77837b; }
:root[data-theme="dark"] .button--outline,
:root[data-theme="dark"] .button--quiet,
:root[data-theme="dark"] .mobile-menu-button,
:root[data-theme="dark"] .mobile-back { color: var(--ink); background: transparent; }
:root[data-theme="dark"] .button--signal { color: #18221c; }

:root[data-theme="dark"] .today-metrics button,
