/* Las etapas pertenecen a la empresa; WhatsApp las usa como índice, no como regla. */
#whatsapp-view .whatsapp-workspace { grid-template-columns: 410px minmax(0, 1fr); }
.whatsapp-master { position: relative; grid-template-columns: 66px minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); }
.whatsapp-list-pane { min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.whatsapp-stage-rail { z-index: 3; width: 66px; min-width: 0; overflow-x: hidden; overflow-y: auto; display: flex; flex-direction: column; gap: 5px; padding: 10px 7px; border-right: 1px solid var(--line); background: color-mix(in srgb, var(--paper) 86%, var(--canvas)); scrollbar-width: thin; transition: width .32s cubic-bezier(.22, 1, .36, 1), box-shadow .2s ease; }
.whatsapp-stage-rail:hover,
.whatsapp-stage-rail:has(.whatsapp-stage-tab:focus-visible) { width: 174px; box-shadow: 18px 0 34px rgb(10 18 12 / 20%); }
.whatsapp-stage-tab { width: 100%; min-height: 48px; display: grid; grid-template-columns: 34px minmax(0, 1fr) 25px; align-items: center; gap: 7px; padding: 6px; overflow: hidden; border: 0; border-radius: 11px; background: transparent; color: var(--muted); text-align: left; transition: color .2s ease, background .2s ease, transform .2s ease; }
.whatsapp-stage-tab:hover { background: color-mix(in srgb, var(--blue) 8%, transparent); color: var(--ink); }
.whatsapp-stage-tab.is-active { background: color-mix(in srgb, var(--blue) 15%, var(--paper)); color: var(--blue); box-shadow: inset 3px 0 var(--blue); }
.whatsapp-stage-index { width: 32px; height: 32px; display: grid; place-items: center; border: 1px solid color-mix(in srgb, currentColor 28%, transparent); border-radius: 9px; font: 800 9px/1 "Cascadia Mono", Consolas, monospace; }
.whatsapp-stage-name { overflow: hidden; opacity: 0; font-size: 10px; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; transform: translateX(-8px); transition: opacity .18s ease .04s, transform .24s ease .04s; }
.whatsapp-stage-count { min-width: 23px; padding: 4px 5px; border-radius: 999px; background: color-mix(in srgb, currentColor 11%, transparent); font: 800 8px/1 "Cascadia Mono", Consolas, monospace; text-align: center; }
.whatsapp-stage-rail:hover .whatsapp-stage-name,
.whatsapp-stage-rail:has(.whatsapp-stage-tab:focus-visible) .whatsapp-stage-name { opacity: 1; transform: translateX(0); }

.whatsapp-chat-menu { width: auto; min-width: 38px; display: inline-flex; align-items: center; justify-content: center; gap: 7px; padding: 0 11px; border: 1px solid transparent; border-radius: 999px; font-size: 11px; font-weight: 800; }
.whatsapp-chat-menu:hover { border-color: var(--line); }
.whatsapp-details-icon { font-size: 20px; font-weight: 400; line-height: 1; }
.whatsapp-details-label { font-size: 9px; letter-spacing: .04em; text-transform: uppercase; }

.lead-sheet-dialog.is-whatsapp-detail { width: min(590px, 100vw); height: 100dvh; max-height: 100dvh; margin: 0 0 0 auto; padding: 0; overflow: hidden; border: 0; border-radius: 18px 0 0 18px; background: var(--canvas); box-shadow: -24px 0 70px rgb(0 0 0 / 28%); animation: whatsapp-detail-in .34s cubic-bezier(.22, 1, .36, 1); }
.lead-sheet-dialog.is-whatsapp-detail::backdrop { background: rgb(8 14 10 / 48%); backdrop-filter: blur(3px); }
.is-whatsapp-detail #lead-sheet-content { height: 100%; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.whatsapp-detail-sheet-head { min-height: 92px; padding: 19px 22px; background: var(--paper); color: var(--ink); border-bottom: 1px solid var(--line); }
.whatsapp-detail-sheet-head p { color: var(--muted); }
.whatsapp-detail-sheet-body { display: flex; flex-direction: column; align-items: stretch; gap: 11px; overflow-y: auto; padding: 12px; }
.whatsapp-detail-sheet-body .detail-card { flex: 0 0 auto; width: 100%; border-radius: 11px; }
.process-overview { display: grid; grid-template-columns: minmax(140px, .65fr) minmax(0, 1.35fr); gap: 10px; padding: 13px; }
.process-current-stage,
.process-next-action,
.process-transitions,
.process-missing-summary { min-width: 0; display: grid; align-content: start; gap: 6px; padding: 13px; border: 1px solid var(--line); border-radius: 9px; background: color-mix(in srgb, var(--paper) 88%, var(--canvas)); }
.process-current-stage { box-shadow: inset 3px 0 var(--blue); }
.process-current-label { color: var(--muted); font-size: 8px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase; }
.process-current-value { color: var(--blue); font: 750 20px/1.05 "Bahnschrift SemiCondensed", "Segoe UI", sans-serif; }
.process-current-stage small,
.process-next-action small { color: var(--muted); font-size: 9px; }
.process-next-action strong { font-size: 12px; line-height: 1.45; }
.process-transitions,
.process-missing-summary { grid-column: 1 / -1; }
.process-transition-list { display: flex; flex-wrap: wrap; gap: 6px; }
.process-transition-chip { padding: 6px 8px; border-radius: 999px; background: color-mix(in srgb, var(--blue) 11%, transparent); color: var(--blue); font-size: 9px; font-weight: 700; }
.process-transition-empty { color: var(--muted); font-size: 10px; }
.process-missing-summary { border-color: color-mix(in srgb, #d59b21 42%, var(--line)); background: color-mix(in srgb, #d59b21 8%, var(--paper)); }
.process-missing-summary strong { font-size: 10px; line-height: 1.45; }

@keyframes whatsapp-detail-in {
  from { opacity: 0; transform: translateX(52px); }
  to { opacity: 1; transform: translateX(0); }
}

@media (max-width: 1050px) and (min-width: 721px) {
  #whatsapp-view .whatsapp-workspace { grid-template-columns: 350px minmax(0, 1fr); }
}

@media (max-width: 720px) {
  .whatsapp-master { grid-template-columns: 1fr; grid-template-rows: auto minmax(0, 1fr); }
  .whatsapp-stage-rail,
  .whatsapp-stage-rail:hover,
  .whatsapp-stage-rail:has(.whatsapp-stage-tab:focus-visible) { width: 100%; flex-direction: row; gap: 6px; padding: 7px 8px; overflow-x: auto; overflow-y: hidden; border-right: 0; border-bottom: 1px solid var(--line); box-shadow: none; scrollbar-width: none; }
  .whatsapp-stage-rail::-webkit-scrollbar { display: none; }
  .whatsapp-stage-tab { width: auto; min-width: max-content; min-height: 38px; grid-template-columns: auto 23px; gap: 6px; padding: 5px 8px; border-radius: 9px; }
  .whatsapp-stage-index { display: none; }
  .whatsapp-stage-name { opacity: 1; font-size: 9px; transform: none; }
  .whatsapp-chat-menu { width: 38px; padding: 0; }
  .whatsapp-details-label { display: none; }
  .lead-sheet-dialog.is-whatsapp-detail { width: 100vw; border-radius: 0; }
  .process-overview { grid-template-columns: 1fr; }
  .process-transitions,
  .process-missing-summary { grid-column: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .whatsapp-master,
  .whatsapp-stage-rail,
  .whatsapp-stage-tab,
  .whatsapp-stage-name,
  .lead-sheet-dialog.is-whatsapp-detail { animation: none; transition: none; }
}

/* Firma SPORTEX: grafito, blanco y lima. Etapas como pestañas, no como barra. */
:root {
  --blue: #18221c;
  --signal: #cfe64e;
}
:root[data-theme="dark"] {
  --blue: #cfe64e;
  --signal: #cfe64e;
}

#whatsapp-view .whatsapp-workspace { grid-template-columns: 370px minmax(0, 1fr); }
.whatsapp-master { grid-template-columns: 1fr; grid-template-rows: auto minmax(0, 1fr); }
.whatsapp-stage-rail,
.whatsapp-stage-rail:hover,
.whatsapp-stage-rail:has(.whatsapp-stage-tab:focus-visible) {
  z-index: 1;
  width: 100%;
  display: flex;
  flex-direction: row;
  gap: 7px;
  padding: 10px 11px 0;
  overflow-x: auto;
  overflow-y: hidden;
  border: 0;
  background: var(--paper);
  box-shadow: inset 0 -1px var(--line);
  scrollbar-width: none;
  transition: none;
}
.whatsapp-stage-rail::-webkit-scrollbar { display: none; }
.whatsapp-stage-tab {
  width: auto;
  min-width: max-content;
  min-height: 40px;
  grid-template-columns: minmax(0, 1fr) 24px;
  gap: 8px;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-bottom-color: transparent;
  border-radius: 10px 10px 3px 3px;
  background: color-mix(in srgb, var(--paper) 94%, white);
  color: var(--ink-soft);
  transform: translateY(1px);
  transition: transform .18s ease, color .18s ease, background .18s ease, border-color .18s ease;
}
.whatsapp-stage-tab:hover {
  border-color: color-mix(in srgb, var(--signal) 60%, var(--line));
  border-bottom-color: transparent;
  background: color-mix(in srgb, var(--signal) 8%, var(--paper));
  color: var(--ink);
  transform: translateY(0);
}
.whatsapp-stage-tab.is-active {
  border-color: var(--signal);
  border-bottom-color: var(--signal);
  background: var(--signal);
  color: #18221c;
  box-shadow: none;
  transform: translateY(0);
}
.whatsapp-stage-index { display: none; }
.whatsapp-stage-name,
.whatsapp-stage-rail:hover .whatsapp-stage-name,
.whatsapp-stage-rail:has(.whatsapp-stage-tab:focus-visible) .whatsapp-stage-name {
  opacity: 1;
  overflow: visible;
  font-size: 9px;
  transform: none;
}
.whatsapp-stage-count { background: rgb(24 34 28 / 10%); color: inherit; }
.whatsapp-row.is-selected { background: color-mix(in srgb, var(--signal) 11%, var(--paper)); box-shadow: inset 3px 0 var(--signal); }
.whatsapp-avatar--detail { border-color: color-mix(in srgb, var(--signal) 55%, var(--line)); background: color-mix(in srgb, var(--signal) 13%, var(--paper)); color: var(--ink); }
.whatsapp-team { color: color-mix(in srgb, var(--signal) 58%, var(--ink)); }
.whatsapp-send { background: var(--signal); color: #18221c; }
.process-current-stage { box-shadow: inset 3px 0 var(--signal); }
.process-current-value,
.process-transition-chip { color: color-mix(in srgb, var(--signal) 62%, var(--ink)); }
.process-transition-chip { background: color-mix(in srgb, var(--signal) 11%, transparent); }

:root[data-theme="dark"] .whatsapp-row.is-selected { background: color-mix(in srgb, var(--signal) 12%, #171d19); }
:root[data-theme="dark"] .whatsapp-avatar--detail { background: color-mix(in srgb, var(--signal) 11%, #171d19); border-color: color-mix(in srgb, var(--signal) 48%, #47534a); color: white; }
:root[data-theme="dark"] .whatsapp-team { color: color-mix(in srgb, var(--signal) 72%, white); }
:root[data-theme="dark"] .whatsapp-chat-pane .message-row.is-delta { background: color-mix(in srgb, var(--signal) 17%, #171d19); color: white; }
:root[data-theme="dark"] .process-current-value,
:root[data-theme="dark"] .process-transition-chip { color: var(--signal); }

@media (max-width: 1050px) and (min-width: 721px) {
  #whatsapp-view .whatsapp-workspace { grid-template-columns: 340px minmax(0, 1fr); }
}

@media (max-width: 720px) {
  .whatsapp-stage-rail,
  .whatsapp-stage-rail:hover,
  .whatsapp-stage-rail:has(.whatsapp-stage-tab:focus-visible) { padding: 8px 8px 0; }
  .whatsapp-stage-tab { min-height: 38px; padding: 6px 9px; }
}

/* Lengüetas de proceso: laterales, independientes y con apertura horizontal. */
.whatsapp-master { position: relative; display: block; }
.whatsapp-list-pane { width: 100%; height: 100%; }
.whatsapp-stage-rail,
.whatsapp-stage-rail:hover,
.whatsapp-stage-rail:has(.whatsapp-stage-tab:focus-visible) {
  position: absolute;
  z-index: 6;
  top: 108px;
  left: 0;
  width: 0;
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 0;
  overflow: visible;
  border: 0;
  background: transparent;
  box-shadow: none;
}
.whatsapp-stage-tab {
  width: 160px;
  min-width: 160px;
  min-height: 42px;
  grid-template-columns: minmax(0, 1fr) 25px;
  gap: 8px;
  padding: 7px 8px 7px 13px;
  border: 1px solid var(--line);
  border-left: 0;
  border-radius: 0 10px 10px 0;
  background: var(--paper);
  color: var(--ink-soft);
  box-shadow: 8px 7px 22px rgb(8 14 10 / 13%);
  transform: translateX(-136px);
  transition: transform .3s cubic-bezier(.22, 1, .36, 1), background .18s ease, color .18s ease, border-color .18s ease;
}
.whatsapp-stage-tab:hover,
.whatsapp-stage-tab:focus-visible {
  z-index: 2;
  border-color: var(--signal);
  border-left: 0;
  background: var(--paper);
  color: var(--ink);
  transform: translateX(0);
}
.whatsapp-stage-tab.is-active {
  border-color: var(--signal);
  border-left: 0;
  background: var(--signal);
  color: #18221c;
  transform: translateX(-128px);
}
.whatsapp-stage-tab.is-active:hover,
.whatsapp-stage-tab.is-active:focus-visible { transform: translateX(0); }
.whatsapp-stage-name { padding-left: 2px; }
.whatsapp-stage-count { justify-self: end; min-width: 23px; background: rgb(24 34 28 / 11%); }

@media (max-width: 720px) {
  .whatsapp-stage-rail,
  .whatsapp-stage-rail:hover,
  .whatsapp-stage-rail:has(.whatsapp-stage-tab:focus-visible) { top: 108px; padding: 0; }
  .whatsapp-stage-tab { width: 146px; min-width: 146px; min-height: 46px; transform: translateX(-126px); }
  .whatsapp-stage-tab.is-active { transform: translateX(-119px); }
  .whatsapp-stage-tab:hover,
  .whatsapp-stage-tab:focus-visible,
  .whatsapp-stage-tab.is-active:hover,
  .whatsapp-stage-tab.is-active:focus-visible { transform: translateX(0); }
}

/* Escritorio: las etapas viven fuera del panel y nunca pisan la lista de chats. */
@media (min-width: 721px) {
  #whatsapp-view {
    --whatsapp-stage-gutter: 50px;
    padding-left: var(--whatsapp-stage-gutter);
  }

  #whatsapp-view .whatsapp-workspace {
    grid-template-columns: 340px minmax(0, 1fr);
    overflow: visible;
  }

  .whatsapp-stage-rail,
  .whatsapp-stage-rail:hover,
  .whatsapp-stage-rail:has(.whatsapp-stage-tab:focus-visible) {
    top: 108px;
    right: 100%;
    left: auto;
    width: var(--whatsapp-stage-gutter);
    gap: 6px;
    align-items: stretch;
  }

  .whatsapp-stage-tab,
  .whatsapp-stage-tab.is-active {
    position: relative;
    width: 100%;
    min-width: 100%;
    min-height: 82px;
    display: grid;
    grid-template-columns: 1fr;
    place-items: center;
    padding: 6px;
    border: 1px solid var(--line);
    border-right: 0;
    border-radius: 11px 0 0 11px;
    box-shadow: -9px 8px 24px rgb(8 14 10 / 11%);
    transform: none;
  }

  .whatsapp-stage-tab:hover,
  .whatsapp-stage-tab:focus-visible,
  .whatsapp-stage-tab.is-active:hover,
  .whatsapp-stage-tab.is-active:focus-visible {
    border-right: 0;
    transform: translateX(-5px);
  }

  .whatsapp-stage-name {
    max-height: 70px;
    overflow: visible;
    padding-left: 0;
    font: 800 8px/1 "Bahnschrift SemiCondensed", "Arial Narrow", sans-serif;
    letter-spacing: .015em;
    line-height: 1;
    text-overflow: clip;
    writing-mode: vertical-rl;
    text-orientation: mixed;
    transform: rotate(180deg);
    white-space: nowrap;
  }

  .whatsapp-stage-count {
    position: absolute;
    top: 5px;
    right: 4px;
    min-width: 17px;
    padding: 2px 4px;
    font-size: 7px;
  }
}

/* TASK-20260816-001 · WhatsApp como sistema visual transversal. */
:root {
  --surface-canvas: #f4f6f2;
  --surface-panel: #ffffff;
  --surface-raised: #f8faf7;
  --surface-input: #ffffff;
  --surface-hover: #f0f4ee;
  --surface-selected: color-mix(in srgb, var(--signal) 14%, var(--surface-panel));
  --surface-disabled: #edf0eb;
  --text-on-strong: #ffffff;
  --focus-ring: color-mix(in srgb, var(--signal) 44%, transparent);
  --selected-edge: var(--signal);
  --interactive-shadow: 0 8px 24px rgb(24 34 28 / 8%);
  --paper: var(--surface-panel);
  --canvas: var(--surface-canvas);
}

:root[data-theme="dark"] {
  --surface-canvas: #0e1310;
  --surface-panel: #171d19;
  --surface-raised: #1d241f;
  --surface-input: #252d27;
  --surface-hover: #202821;
  --surface-selected: color-mix(in srgb, var(--signal) 12%, #171d19);
  --surface-disabled: #242b26;
  --text-on-strong: #edf3ee;
  --focus-ring: color-mix(in srgb, var(--signal) 38%, transparent);
  --interactive-shadow: 0 10px 30px rgb(0 0 0 / 28%);
}

body,
.app-shell,
.workspace,
.content { background: var(--surface-canvas); color: var(--ink); }

.topbar,
.production-track,
.today-board,
.lead-master,
.lead-detail,
.detail-card,
.commercial-card,
.ledger,
.crm-filterbar,
.crm-workspace,
.lead-focus-head,
.lead-work-pane,
.draft-area,
.lead-mobile-tabs,
.candidate-panel,
.settings-reset,
.results-panel,
.module-card,
.candidate-row,
.sync-state,
.whatsapp-workspace,
.whatsapp-master,
.whatsapp-detail,
.whatsapp-row,
.sheet-actions,
.message-quote,
.confirmation-check,
.segmented span,
dialog { background: var(--surface-panel); color: var(--ink); }

input,
select,
textarea,
.whatsapp-composer-input { background: var(--surface-input); color: var(--ink); border-color: var(--line); }

.today-row,
.ledger-row,
.lead-row,
.whatsapp-row,
.stage-station,
.today-metrics button,
.nav-item,
.button,
.whatsapp-chat-menu { transition: background-color .16s ease, border-color .16s ease, color .16s ease, box-shadow .16s ease, transform .16s ease; }

.today-row:hover,
.ledger-row:hover,
.lead-row:hover,
.whatsapp-row:hover,
.stage-station:hover,
.button--quiet:hover,
.whatsapp-chat-menu:hover { background: var(--surface-hover); color: var(--ink); }

.lead-row.is-selected,
.whatsapp-row.is-selected,
.stage-station.is-filtered,
.today-metrics button.is-selected,
.today-metrics button:hover {
  background: var(--surface-selected);
  color: var(--ink);
  border-color: color-mix(in srgb, var(--selected-edge) 58%, var(--line));
