#whatsapp-view .whatsapp-tabbed-panel-frame__surface { fill: var(--whatsapp-panel-surface); }
#whatsapp-view .whatsapp-tabbed-panel-frame__active-surface { fill: var(--whatsapp-panel-surface); }
#whatsapp-view .whatsapp-tabbed-panel-frame__inactive { fill: url("#whatsapp-tab-inactive-gradient"); }
#whatsapp-view .whatsapp-tabbed-panel-frame__outline {
  fill: none;
  stroke: url("#whatsapp-panel-outline-stroke");
  stroke-width: 1;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}
#whatsapp-view .whatsapp-tabbed-panel-frame__inactive-outline {
  fill: none;
  stroke: var(--whatsapp-tab-border);
  stroke-width: 1;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}
#whatsapp-view .whatsapp-tabbed-panel-frame__active-contour,
#whatsapp-view .whatsapp-tabbed-panel-frame__active-contour-outline {
  fill: none;
  stroke: url("#whatsapp-active-contour-stroke");
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
  pointer-events: none;
}
#whatsapp-view .whatsapp-tabbed-panel-frame__active-contour--outer {
  stroke-width: 2;
  opacity: .035;
  filter: url("#whatsapp-tab-active-halo-outer");
}
#whatsapp-view .whatsapp-tabbed-panel-frame__active-contour--near {
  stroke-width: 1.5;
  opacity: .08;
  filter: url("#whatsapp-tab-active-halo-near");
}
#whatsapp-view .whatsapp-tabbed-panel-frame__active-contour-outline {
  stroke-width: 1;
}
#whatsapp-view .whatsapp-tabbed-panel-frame__active-halo {
  fill: none;
  stroke: url("#whatsapp-active-contour-stroke");
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
  pointer-events: none;
}
#whatsapp-view .whatsapp-tabbed-panel-frame__active-halo--outer {
  stroke-width: 2;
  opacity: .07;
  filter: url("#whatsapp-tab-active-halo-outer");
}
#whatsapp-view .whatsapp-tabbed-panel-frame__active-halo--near {
  stroke-width: 1.5;
  opacity: .21;
  filter: url("#whatsapp-tab-active-halo-near");
}
#whatsapp-view .whatsapp-tabbed-panel-frame__active-outline {
  fill: none;
  stroke: url("#whatsapp-active-contour-stroke");
  stroke-width: 1.25;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}
#whatsapp-view .whatsapp-stage-bar {
  position: relative;
  z-index: 2;
  min-width: 0;
  display: block;
  padding: 0 29px;
  background: transparent;
}
#whatsapp-view .whatsapp-process-tabs {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 67px;
  display: flex;
  align-items: stretch;
  overflow-x: auto;
  overflow-y: visible;
  scrollbar-width: none;
}
#whatsapp-view .whatsapp-process-tabs::-webkit-scrollbar { display: none; }
#whatsapp-view .whatsapp-process-tab {
  position: relative;
  z-index: 1;
  flex: 0 0 180px;
  width: 180px;
  min-width: 180px;
  max-width: 180px;
  height: 67px;
  margin: 0 -1px 0 0;
  padding: 0;
  overflow: visible;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: #a6aca9;
  text-align: left;
  transition: color .16s ease;
}
#whatsapp-view .whatsapp-process-tab.is-active { z-index: 2; color: #f2f5f1; }
#whatsapp-view .whatsapp-process-tab:hover:not(.is-active) { color: #d4dad5; }
#whatsapp-view .whatsapp-process-tab:focus-visible {
  outline: 1px solid #89948d;
  outline-offset: -5px;
}
#whatsapp-view .whatsapp-process-tab__content {
  position: relative;
  z-index: 1;
  box-sizing: border-box;
  width: 100%;
  height: 67px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 0 24px;
  transform: translateY(-1px);
}
#whatsapp-view .whatsapp-process-tab__icon {
  flex: 0 0 18px;
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1;
}
#whatsapp-view .whatsapp-process-tab:not(.is-active) .whatsapp-process-tab__icon { color: #9ca49f; }
#whatsapp-view .whatsapp-process-tab.is-active .whatsapp-process-tab__icon { color: var(--whatsapp-tab-active-outline); }
#whatsapp-view .whatsapp-process-tab__name {
  overflow: hidden;
  color: inherit;
  font: 500 12px/1.1 "Segoe UI", sans-serif;
  letter-spacing: -.01em;
  text-overflow: ellipsis;
  white-space: nowrap;
}
#whatsapp-view .whatsapp-process-tab.is-active .whatsapp-process-tab__name { font-weight: 600; }
#whatsapp-view .whatsapp-process-tab__count {
  position: absolute;
  top: 13px;
  right: 38px;
  color: var(--whatsapp-tab-active-outline);
  font: 700 9px/1 "Cascadia Mono", Consolas, monospace;
}
#whatsapp-view .whatsapp-process-tab.is-active .whatsapp-process-tab__count { color: var(--whatsapp-tab-active-outline); }
#whatsapp-view .whatsapp-workspace {
  position: relative;
  z-index: 1;
  height: auto;
  min-height: 0;
  grid-template-columns: 410px minmax(0, 1fr);
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  clip-path: inset(1px);
}
#whatsapp-view .whatsapp-master,
#whatsapp-view .whatsapp-detail { background-color: var(--whatsapp-panel-surface); }
#whatsapp-view .whatsapp-master {
  background-image:
    linear-gradient(180deg, transparent 0, var(--whatsapp-panel-surface) 120px),
    linear-gradient(90deg, #131915 0, #131915 20%, #181d17 55%, #181d17 100%);
}
#whatsapp-view .whatsapp-detail {
  background-image: linear-gradient(180deg, #191e16 0, #191e16 16px, #141916 120px, #101412 100%);
}
#whatsapp-view .whatsapp-master-head,
#whatsapp-view .whatsapp-chat-head { background: var(--whatsapp-panel-surface); }
#whatsapp-view .whatsapp-master-head {
  background-image: linear-gradient(90deg, #131915 0, #131915 20%, #181d17 55%, #181d17 100%);
}
#whatsapp-view .whatsapp-master-head {
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-areas: "search edit" "unread edit";
  align-items: center;
  gap: 9px 10px;
  padding: 14px;
}
#whatsapp-view .whatsapp-master-head > div { display: none; }
#whatsapp-view .whatsapp-search { grid-area: search; }
#whatsapp-view #whatsapp-unread-filter { grid-area: unread; }
#whatsapp-view #whatsapp-stage-config {
  position: static;
  grid-area: edit;
  width: auto;
  min-width: 76px;
  min-height: 30px;
  margin: 0;
  padding: 6px 8px;
  border-color: #334037;
  border-radius: 6px;
  background: #151d17;
  color: #d4dbd4;
  font-size: 9px;
}
#whatsapp-view #whatsapp-stage-config:hover,
#whatsapp-view #whatsapp-stage-config:focus-visible {
  border-color: var(--whatsapp-tab-active-outline);
  background: #202a22;
  color: #f4f7f2;
}
@media (max-width: 900px) {
  #whatsapp-view { padding: 0 7px 7px; }
  #whatsapp-view .whatsapp-stage-bar { padding: 0 29px; }
  #whatsapp-view .whatsapp-workspace { grid-template-columns: minmax(280px, 38%) minmax(0, 1fr); }
}
@media (max-width: 1100px) {
  #whatsapp-view {
    width: 100%;
    margin-left: 0;
  }
}
@media (max-width: 720px) {
  #whatsapp-view { height: calc(100vh - 90px); }
  #whatsapp-view .whatsapp-workspace-shell { min-height: 0; grid-template-rows: 67px minmax(0, 1fr); }
  #whatsapp-view .whatsapp-stage-bar { padding: 0 29px; }
  #whatsapp-view .whatsapp-process-tabs,
  #whatsapp-view .whatsapp-process-tab,
  #whatsapp-view .whatsapp-process-tab__content { height: 67px; }
  #whatsapp-view .whatsapp-process-tab {
    width: 180px;
    min-width: 180px;
    max-width: 180px;
  }
  #whatsapp-view .whatsapp-process-tab__content { padding: 0 24px; }
  #whatsapp-view .whatsapp-process-tab__count { top: 10px; right: 30px; }
  #whatsapp-view .whatsapp-workspace { grid-template-columns: 1fr; }
}
@media (prefers-reduced-motion: reduce) {
  #whatsapp-view .whatsapp-process-tab { transition: none; }
}
